// Independent implementation of the official anonymous H5 JSON protocol.
// Reference: keiyoushi/extensions-source@dbf6c05d6a9520c60533f1626616263522bbe71a
// src/zh/iqiyi (Apache-2.0, reference only; no upstream code copied).
// Public chapters only. authPass is authoritative; no account, cookie or paywall bypass.
var HOME = 'https://bud.m.iqiyi.com';
var API = 'https://comic.iqiyi.com';
var APP_KEY = '3sj8xof48xjf4tk9f4tk9ypgk9ypg5up';
var QIYI_ID = Array.from({length: 32}, function () { return Math.floor(Math.random() * 16).toString(16); }).join('');
function md5(text) {
  // RFC 1321 compression on ASCII: the signed query is already percent-encoded.
  var size = Math.ceil((text.length + 9) / 64) * 16, words = new Array(size).fill(0);
  for (var i = 0; i < text.length; i++) words[i >> 2] |= text.charCodeAt(i) << ((i % 4) * 8);
  words[text.length >> 2] |= 128 << ((text.length % 4) * 8);
  words[size - 2] = (text.length * 8) | 0;
  words[size - 1] = Math.floor(text.length / 536870912);
  var state = [1732584193, -271733879, -1732584194, 271733878];
  var shifts = [[7,12,17,22], [5,9,14,20], [4,11,16,23], [6,10,15,21]];
  for (var offset = 0; offset < size; offset += 16) {
    var a = state[0], b = state[1], c = state[2], d = state[3];
    for (var j = 0; j < 64; j++) {
      var f, g, round = Math.floor(j / 16);
      if (round === 0) { f = (b & c) | (~b & d); g = j; }
      else if (round === 1) { f = (d & b) | (~d & c); g = (5 * j + 1) % 16; }
      else if (round === 2) { f = b ^ c ^ d; g = (3 * j + 5) % 16; }
      else { f = c ^ (b | ~d); g = (7 * j) % 16; }
      var sum = (a + f + Math.floor(Math.abs(Math.sin(j + 1)) * 4294967296) + words[offset + g]) | 0;
      var shift = shifts[round][j % 4], previous = d;
      d = c; c = b; b = (b + ((sum << shift) | (sum >>> (32 - shift)))) | 0; a = previous;
    }
    state[0] = (state[0] + a) | 0; state[1] = (state[1] + b) | 0;
    state[2] = (state[2] + c) | 0; state[3] = (state[3] + d) | 0;
  }
  var out = '';
  for (var s = 0; s < 4; s++) for (var n = 0; n < 4; n++) out += ('0' + ((state[s] >>> (n * 8)) & 255).toString(16)).slice(-2);
  return out;
}
function encode(value) {
  // Match OkHttp addQueryParameter: encode characters encodeURIComponent leaves unescaped.
  return encodeURIComponent(String(value)).replace(/[!'()*]/g, function (c) { return '%' + c.charCodeAt(0).toString(16).toUpperCase(); });
}
async function api(path, args) {
  var pairs = args.concat([['qiyiId', QIYI_ID], ['timeStamp', String(Date.now())], ['srcPlatform','15'], ['appVer','3.0.0'], ['agentVersion','h5'], ['agentType','115']]);
  var query = pairs.map(function (p) { return encode(p[0]) + '=' + encode(p[1]); }).join('&');
  var response = await triomi.fetch(API + path + '?' + query, {headers: {md5: md5(path + query + APP_KEY)}});
  if (response.status !== 200) throw new Error('爱奇艺叭嗒：HTTP ' + response.status);
  if (response.url && !/^https:\/\/comic\.iqiyi\.com\//.test(response.url)) throw new Error('爱奇艺叭嗒：接口重新导向到非官方地址');
  var result;
  try { result = JSON.parse(response.body); } catch (_) { throw new Error('爱奇艺叭嗒：官方接口未返回 JSON，可能暂时不可用'); }
  // Detail currently uses A00001 even for successful complete data.
  if (!result || !result.data || (result.code !== 'A00000' && result.code !== 'A00001')) throw new Error('爱奇艺叭嗒：官方接口拒绝请求或需要登录');
  return result.data;
}
function id(value) {
  var text = String(value);
  if (!/^[1-9]\d*$/.test(text)) throw new Error('爱奇艺叭嗒：漫画或章节编号无效');
  return text;
}
function comicId(url) {
  var match = String(url).match(/^https:\/\/bud\.m\.iqiyi\.com\/(?:comic\/)?detail(?:\/|_)([1-9]\d*)(?:\.html)?(?:[?#].*)?$/);
  if (!match) throw new Error('爱奇艺叭嗒：仅支持官方漫画详情地址');
  return match[1];
}
function picture(url) {
  if (!url) return '';
  var value = String(url);
  if (/^http:\/\/(?:[a-z0-9-]+\.)*iqiyipic\.com\//i.test(value)) value = value.replace(/^http:/, 'https:');
  if (!/^https:\/\/[^/]+\//.test(value)) throw new Error('爱奇艺叭嗒：图片地址不是安全的公开网址');
  return value;
}
function item(row, searchMode) {
  var value = id(searchMode ? row.id : row.comicId);
  if (!row.title) throw new Error('爱奇艺叭嗒：作品列表格式已变更');
  return {remoteId: value, title: row.title, url: HOME + '/detail/' + value, coverUrl: picture(searchMode ? row.image_url : row.pic)};
}
async function discover(url, page) {
  if ((page || 1) > 1) return [];
  var data = await api('/views/1.0/classify/popularity_list', [['type','1'], ['pageSize','100'], ['pageNo','1']]);
  if (!Array.isArray(data.popularityList)) throw new Error('爱奇艺叭嗒：人气列表格式已变更');
  return data.popularityList.map(function (row) { return item(row, false); });
}
async function search(keyword, page) {
  if ((page || 1) > 1) return [];
  var data = await api('/views/1.0/search', [['key',keyword], ['page_num','1']]);
  if (!Array.isArray(data.docinfos)) throw new Error('爱奇艺叭嗒：搜索列表格式已变更');
  return data.docinfos.filter(function (row) { return row.albumDocInfo && row.albumDocInfo.comics; }).map(function (row) { return item(row.albumDocInfo.comics, true); });
}
async function detail(url, snapshot) {
  var value = comicId(url), data = await api('/views/1.0/comicDetail', [['comicId',value]]);
  if (String(data.comicId) !== value || !data.title || !Array.isArray(data.episodes)) throw new Error('爱奇艺叭嗒：详情或章节格式已变更');
  var seen = {}, chapters = data.episodes.map(function (row, index) {
    var episode = id(row.episodeId);
    if (String(row.comicId) !== value || !row.episodeTitle || !Number.isFinite(Number(row.episodeOrder)) || seen[episode]) throw new Error('爱奇艺叭嗒：章节编号、顺序或归属异常');
    seen[episode] = true;
    return {remoteId: episode, title: row.episodeOrder + ' ' + row.episodeTitle, url: HOME + '/reader/' + value + '_' + episode + '.html', number: Number(row.episodeOrder), volumeTitle: '章节', index: index};
  });
  chapters.sort(function (a,b) { return a.number - b.number || a.index - b.index; });
  var result = Object.assign({}, snapshot || {}, {remoteId: value, title: data.title, url: HOME + '/detail/' + value, coverUrl: picture(data.pic), author: data.authorsName || '', description: data.brief || '', tags: (data.comicTags || []).filter(function (tag) { return typeof tag === 'string' && tag.trim(); }), status: data.serializeStatus === 1 ? 'ongoing' : data.serializeStatus === 2 ? 'completed' : 'unknown'});
  return {item: result, chapters: chapters};
}
async function content(url, chapter) {
  var match = String(url).match(/^https:\/\/bud\.m\.iqiyi\.com\/reader\/([1-9]\d*)_([1-9]\d*)\.html$/);
  if (!match || (chapter && chapter.remoteId && String(chapter.remoteId) !== match[2])) throw new Error('爱奇艺叭嗒：章节地址或编号无效');
  var data = await api('/read/pcw/1.0/read', [['episodeId',match[2]]]);
  if (data.authPass !== 1) throw new Error('爱奇艺叭嗒：此章付费、需要登录或无公开阅读权限，请到官方阅读');
  if (!Array.isArray(data.content) || !data.content.length) throw new Error('爱奇艺叭嗒：此章未返回公开正文图片');
  if (data.pageCount != null && Number(data.pageCount) !== data.content.length) throw new Error('爱奇艺叭嗒：正文图片不完整，无法读取完整章节');
  var pages = data.content.map(function (row, index) { return {url: picture(row.imageUrl), order: row.pageOrder == null ? index + 1 : Number(row.pageOrder)}; });
  var seen = {};
  pages.forEach(function (p) { if (!p.url || !Number.isFinite(p.order) || seen[p.order]) throw new Error('爱奇艺叭嗒：正文图片顺序或地址异常'); seen[p.order] = true; });
  pages.sort(function (a,b) { return a.order - b.order; });
  return {images: pages.map(function (p) { return p.url; })};
}
